geJ(a){return"\u0412\u0435\u0440\u0441\u0438\u044f"},
gen(a){return"\u0418\u0437\u0442\u0435\u0433\u043b\u0438"},
gep(){return"\u0422\u043e\u0437\u0438 \u0438\u043c\u0435\u0439\u043b \u043d\u0435 \u0435 \u0432\u0430\u043b\u0438\u0434\u0435\u043d"},
