gdf(){return"\u0394\u03b7\u03bc\u03b9\u03bf\u03c5\u03c1\u03b3\u03ae\u03c3\u03c4\u03b5 \u03c4\u03bf \u03b5\u03c0\u03b1\u03b3\u03b3\u03b5\u03bb\u03bc\u03b1\u03c4\u03b9\u03ba\u03cc \u03c3\u03b1\u03c2 \u03bc\u03ac\u03b8\u03b7\u03bc\u03b1"},
gd8(){return"\u0395\u03c0\u03b5\u03ba\u03c4\u03b5\u03af\u03bd\u03b5\u03c4\u03b5 \u03c4\u03bf \u03b5\u03c0\u03b9\u03c7\u03b5\u03b9\u03c1\u03b7\u03bc\u03b1\u03c4\u03b9\u03ba\u03cc \u03c3\u03b1\u03c2 \u03bc\u03bf\u03bd\u03c4\u03ad\u03bb\u03bf"},
gd_(){return"\u0395\u03bb\u03ba\u03cd\u03c3\u03c4\u03b5 \u03c4\u03bf \u03ba\u03bf\u03b9\u03bd\u03cc \u03c3\u03b1\u03c2 \u03bc\u03b5 \u03c3\u03cd\u03bd\u03c4\u03bf\u03bc\u03b1 \u03b2\u03af\u03bd\u03c4\u03b5\u03bf. \u0395\u03c0\u03b1\u03bb\u03b7\u03b8\u03b5\u03cd\u03c3\u03c4\u03b5 \u03c4\u03bf\u03bd \u03bb\u03bf\u03b3\u03b1\u03c1\u03b9\u03b1\u03c3\u03bc\u03cc \u03c3\u03b1\u03c2 \u03ba\u03b1\u03b9 \u03bf\u03c1\u03af\u03c3\u03c4\u03b5 \u03bc\u03b7\u03bd\u03b9\u03b1\u03af\u03b1 \u03c3\u03c5\u03bd\u03b4\u03c1\u03bf\u03bc\u03ae \u03bc\u03b5\u03c4\u03b1\u03be\u03cd $5 \u03ba\u03b1\u03b9 $100 \u03b4\u03bf\u03bb\u03b1\u03c1\u03af\u03c9\u03bd \u03b3\u03b9\u03b1 \u03b4\u03b7\u03bc\u03cc\u03c3\u03b9\u03b1 \u03bc\u03b1\u03b8\u03ae\u03bc\u03b1\u03c4\u03b1, \u03b1\u03c0\u03bf\u03ba\u03bb\u03b5\u03b9\u03c3\u03c4\u03b9\u03ba\u03cc \u03c0\u03b5\u03c1\u03b9\u03b5\u03c7\u03cc\u03bc\u03b5\u03bd\u03bf \u03ae \u03c0\u03c1\u03bf\u03b3\u03c1\u03b1\u03bc\u03bc\u03b1\u03c4\u03b9\u03c3\u03bc\u03ad\u03bd\u03b5\u03c2 \u03ba\u03bb\u03ae\u03c3\u03b5\u03b9\u03c2."},
gd1(){return"\u0394\u03b9\u03b4\u03ac\u03be\u03c4\u03b5 \u03bc\u03ad\u03c3\u03c9 \u03c0\u03c1\u03bf\u03b3\u03c1\u03b1\u03bc\u03bc\u03b1\u03c4\u03b9\u03c3\u03bc\u03ad\u03bd\u03c9\u03bd \u03ba\u03bb\u03ae\u03c3\u03b5\u03c9\u03bd. \u03a0\u03c1\u03bf\u03c3\u03c6\u03ad\u03c1\u03b5\u03c4\u03b5 \u03bf\u03bc\u03b1\u03b4\u03b9\u03ba\u03ad\u03c2 \u03ae \u03b1\u03c4\u03bf\u03bc\u03b9\u03ba\u03ad\u03c2 \u03c3\u03c5\u03bd\u03b5\u03b4\u03c1\u03af\u03b5\u03c2, \u03c7\u03c1\u03b5\u03ce\u03bd\u03bf\u03bd\u03c4\u03b1\u03c2 \u03b1\u03c0\u03cc $5 \u03ad\u03c9\u03c2 $100 \u03b4\u03bf\u03bb\u03ac\u03c1\u03b9\u03b1 \u03b1\u03bd\u03ac \u03ba\u03bb\u03ae\u03c3\u03b7."},
gd2(){return"\u039a\u03b5\u03c1\u03b4\u03af\u03c3\u03c4\u03b5 \u03c7\u03c1\u03ae\u03bc\u03b1\u03c4\u03b1 \u03bc\u03b5 \u03c4\u03b1 \u03bc\u03b1\u03b8\u03ae\u03bc\u03b1\u03c4\u03ac \u03c3\u03b1\u03c2 \u03bc\u03b5 \u03c4\u03b9\u03bc\u03ad\u03c2 \u03b1\u03c0\u03cc $20 \u03ad\u03c9\u03c2 $500 \u03b4\u03bf\u03bb\u03ac\u03c1\u03b9\u03b1. \u039c\u03bf\u03b9\u03c1\u03b1\u03c3\u03c4\u03b5\u03af\u03c4\u03b5 \u03c4\u03bf \u03c0\u03ac\u03b8\u03bf\u03c2 \u03c3\u03b1\u03c2 \u03bc\u03ad\u03c3\u03b1 \u03b1\u03c0\u03cc \u03bc\u03b1\u03b8\u03ae\u03bc\u03b1\u03c4\u03b1, \u03b4\u03c1\u03b1\u03c3\u03c4\u03b7\u03c1\u03b9\u03cc\u03c4\u03b7\u03c4\u03b5\u03c2 \u03ba\u03b1\u03b9 \u03b1\u03be\u03b9\u03bf\u03bb\u03bf\u03b3\u03ae\u03c3\u03b5\u03b9\u03c2, \u03ba\u03b1\u03b9 \u03c0\u03c1\u03bf\u03c3\u03c6\u03ad\u03c1\u03b5\u03c4\u03b5 \u03c0\u03b9\u03c3\u03c4\u03bf\u03c0\u03bf\u03af\u03b7\u03c3\u03b7 \u03c3\u03c4\u03bf \u03c4\u03ad\u03bb\u03bf\u03c2."},
gd3(){return"\u0394\u03b7\u03bc\u03b9\u03bf\u03c5\u03c1\u03b3\u03ae\u03c3\u03c4\u03b5 \u03b5\u03bd\u03c4\u03c5\u03c0\u03c9\u03c3\u03b9\u03b1\u03ba\u03ac \u03bc\u03b1\u03b8\u03ae\u03bc\u03b1\u03c4\u03b1 \u03bc\u03b5 \u03b5\u03bb\u03ba\u03c5\u03c3\u03c4\u03b9\u03ba\u03ad\u03c2 \u03b5\u03b9\u03c3\u03b1\u03b3\u03c9\u03b3\u03ad\u03c2, podcasts, \u03c0\u03bf\u03bb\u03c5\u03bc\u03b5\u03c3\u03b9\u03ba\u03ad\u03c2 \u03b9\u03c3\u03c4\u03bf\u03c1\u03af\u03b5\u03c2 \u03ae \u03ad\u03b3\u03b3\u03c1\u03b1\u03c6\u03b1. \u03a0\u03b5\u03c1\u03b9\u03bb\u03b1\u03bc\u03b2\u03ac\u03bd\u03bf\u03c5\u03bd \u03c0\u03bf\u03bb\u03bb\u03b1\u03c0\u03bb\u03ad\u03c2 \u03b5\u03c1\u03c9\u03c4\u03ae\u03c3\u03b5\u03b9\u03c2 \u03bc\u03b5 \u03ae\u03c7\u03bf, \u03b2\u03af\u03bd\u03c4\u03b5\u03bf, \u03b3\u03c1\u03b1\u03c6\u03b9\u03ba\u03ac \u03ba\u03b1\u03b9 \u03bc\u03b1\u03b8\u03b7\u03bc\u03b1\u03c4\u03b9\u03ba\u03ad\u03c2 \u03b5\u03be\u03b9\u03c3\u03ce\u03c3\u03b5\u03b9\u03c2. \u039b\u03ac\u03b2\u03b5\u03c4\u03b5 \u03c6\u03b9\u03bb\u03bf\u03b4\u03c9\u03c1\u03ae\u03bc\u03b1\u03c4\u03b1 \u03b1\u03c0\u03cc $2 \u03ad\u03c9\u03c2 1000 \u03b4\u03bf\u03bb\u03ac\u03c1\u03b9\u03b1."},
gd4(){return"\u03a3\u03c5\u03bd\u03b4\u03b5\u03b8\u03b5\u03af\u03c4\u03b5 \u03bc\u03b5 \u03bc\u03b9\u03b1 \u03c0\u03bf\u03b9\u03ba\u03b9\u03bb\u03cc\u03bc\u03bf\u03c1\u03c6\u03b7 \u03ba\u03bf\u03b9\u03bd\u03cc\u03c4\u03b7\u03c4\u03b1 \u03b3\u03b9\u03b1 \u03bd\u03b1 \u03b3\u03bd\u03c9\u03c1\u03af\u03c3\u03b5\u03c4\u03b5 \u03bd\u03ad\u03bf\u03c5\u03c2 \u03b1\u03bd\u03b8\u03c1\u03ce\u03c0\u03bf\u03c5\u03c2, \u03bd\u03b1 \u03b5\u03be\u03b1\u03c3\u03ba\u03b7\u03b8\u03b5\u03af\u03c4\u03b5 \u03c3\u03b5 \u03b3\u03bb\u03ce\u03c3\u03c3\u03b5\u03c2, \u03bd\u03b1 \u03c0\u03bf\u03c5\u03bb\u03ae\u03c3\u03b5\u03c4\u03b5 \u03bc\u03b1\u03b8\u03ae\u03bc\u03b1\u03c4\u03b1 \u03ae \u03b1\u03c0\u03bb\u03ce\u03c2 \u03bd\u03b1 \u03c3\u03c5\u03bd\u03bf\u03bc\u03b9\u03bb\u03ae\u03c3\u03b5\u03c4\u03b5 \u03ba\u03b1\u03b9 \u03bd\u03b1 \u03c0\u03c1\u03bf\u03b3\u03c1\u03b1\u03bc\u03bc\u03b1\u03c4\u03af\u03c3\u03b5\u03c4\u03b5 \u03ba\u03bb\u03ae\u03c3\u03b5\u03b9\u03c2 \u03b3\u03b9\u03b1 \u03b4\u03b9\u03b4\u03b1\u03c3\u03ba\u03b1\u03bb\u03af\u03b1."},
gd5(){return"\u0395\u03be\u03b1\u03c3\u03ba\u03b7\u03b8\u03b5\u03af\u03c4\u03b5 \u03c3\u03b5 \u03b3\u03bb\u03ce\u03c3\u03c3\u03b5\u03c2 \u03bc\u03b5 \u03c4\u03b5\u03c7\u03bd\u03b7\u03c4\u03ae \u03bd\u03bf\u03b7\u03bc\u03bf\u03c3\u03cd\u03bd\u03b7 \u03b3\u03b9\u03b1 \u03bd\u03b1 \u03b5\u03bd\u03b9\u03c3\u03c7\u03cd\u03c3\u03b5\u03c4\u03b5 \u03c4\u03b7\u03bd \u03ba\u03b1\u03c4\u03b1\u03bd\u03cc\u03b7\u03c3\u03ae \u03c3\u03b1\u03c2. \u0394\u03b9\u03b1\u03b8\u03ad\u03c3\u03b9\u03bc\u03bf \u03c3\u03b5 \u03ad\u03be\u03b9 \u03b3\u03bb\u03ce\u03c3\u03c3\u03b5\u03c2."},
gd6(){return"\u0391\u03c0\u03bf\u03c6\u03cd\u03b3\u03b5\u03c4\u03b5 \u03c4\u03b1 \u03b1\u03ba\u03c1\u03b9\u03b2\u03ac \u03c3\u03c5\u03c3\u03c4\u03ae\u03bc\u03b1\u03c4\u03b1 LMS. \u0395\u03b4\u03ce \u03bc\u03c0\u03bf\u03c1\u03b5\u03af\u03c4\u03b5 \u03bd\u03b1 \u03b4\u03b7\u03bc\u03b9\u03bf\u03c5\u03c1\u03b3\u03ae\u03c3\u03b5\u03c4\u03b5 \u03bc\u03b1\u03b8\u03ae\u03bc\u03b1\u03c4\u03b1 \u03c5\u03c8\u03b7\u03bb\u03ae\u03c2 \u03c0\u03bf\u03b9\u03cc\u03c4\u03b7\u03c4\u03b1\u03c2 \u03c7\u03c9\u03c1\u03af\u03c2 \u03bd\u03b1 \u03b8\u03c5\u03c3\u03b9\u03ac\u03c3\u03b5\u03c4\u03b5 \u03c4\u03b7\u03bd \u03ac\u03bd\u03b5\u03c3\u03b7 \u03ae \u03c4\u03b7\u03bd \u03c0\u03bf\u03b9\u03cc\u03c4\u03b7\u03c4\u03b1 \u03b3\u03b9\u03b1 \u03c4\u03bf\u03c5\u03c2 \u03bc\u03b1\u03b8\u03b7\u03c4\u03ad\u03c2 \u03c3\u03b1\u03c2."},
