gee(){return"\u10ec\u10d4\u10e0\u10d4\u10d7 \u10d7\u10e5\u10d5\u10d4\u10dc\u10d8 \u10e1\u10d0\u10ee\u10d4\u10da\u10d8 \u10d0\u10e5"},
gcY(){return"\u10ec\u10d4\u10e0\u10d4\u10d7 \u10d7\u10e5\u10d5\u10d4\u10dc\u10d8 \u10d4\u10da.\u10e4\u10dd\u10e1\u10e2\u10d0 \u10d0\u10e5"},
ge1(){return"\u10e8\u10d4\u10d8\u10e7\u10d5\u10d0\u10dc\u10d4\u10d7 \u10e1\u10d0\u10ee\u10d4\u10da\u10d8"},
