gdI(){return"\u10de\u10da\u10d0\u10e2\u10e4\u10dd\u10e0\u10db\u10d8\u10e1 \u10ec\u10d4\u10e1\u10d4\u10d1\u10d8"},
gdL(){return"\u10db\u10dd\u10db\u10e1\u10d0\u10ee\u10e3\u10e0\u10d4\u10d1\u10d8\u10e1 \u10de\u10d8\u10e0\u10dd\u10d1\u10d4\u10d1\u10d8"},
gcD(){return"\u10ee\u10e8\u10d8\u10e0\u10d0\u10d3 \u10d3\u10d0\u10e1\u10db\u10e3\u10da\u10d8 \u10d9\u10d8\u10d7\u10ee\u10d5\u10d4\u10d1\u10d8"},
gdC(){return"\u10d8\u10e3\u10e0\u10d8\u10d3\u10d8\u10e3\u10da\u10d8 \u10d8\u10dc\u10e4\u10dd\u10e0\u10db\u10d0\u10ea\u10d8\u10d0"},
gdj(){return"\u10e7\u10d5\u10d4\u10da\u10d0 \u10e3\u10e4\u10da\u10d4\u10d1\u10d0 \u10d3\u10d0\u10ea\u10e3\u10da\u10d8\u10d0"},
gcN(){return"\u10e8\u10d4\u10e1\u10d5\u10da\u10d0"},
gds(){return"\u10d2\u10d0\u10d2\u10e0\u10eb\u10d4\u10da\u10d4\u10d1\u10d0"},
gex(){return"\u10d7\u10e3 \u10d2\u10d0\u10e5\u10d5\u10d7 Edhomy \u10d0\u10dc\u10d2\u10d0\u10e0\u10d8\u10e8\u10d8, \u10d2\u10d7\u10ee\u10dd\u10d5\u10d7 \u10e8\u10d4\u10e1\u10d5\u10da\u10d0 \u10d5\u10d8\u10d3\u10d4\u10dd \u10e8\u10d4\u10ee\u10d5\u10d4\u10d3\u10e0\u10d4\u10d1\u10e8\u10d8 \u10d3\u10d0\u10e1\u10ec\u10e0\u10d4\u10d1\u10d8\u10e1\u10d7\u10d5\u10d8\u10e1"},
gcV(){return"\u10d8\u10e2\u10d5\u10d8\u10e0\u10d7\u10d4\u10d1\u10d0"},
gdq(a){return"\u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d8"},
gdl(){return"\u10d8\u10dc\u10e2\u10d4\u10e0\u10dc\u10d4\u10e2\u10d8\u10e1 \u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d8 \u10d0\u10e0 \u10d0\u10e0\u10d8\u10e1. \u10d2\u10d7\u10ee\u10dd\u10d5\u10d7 \u10e8\u10d4\u10d0\u10db\u10dd\u10ec\u10db\u10dd\u10d7 \u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d8"},
ge8(){return"\u10d0\u10e0 \u10db\u10dd\u10d8\u10eb\u10d4\u10d1\u10dc\u10d0"},
ge7(){return"Google-\u10d6\u10d4 \u10d0\u10e0 \u10d0\u10e0\u10e1\u10d4\u10d1\u10dd\u10d1\u10e1 Edhomy \u10d0\u10dc\u10d2\u10d0\u10e0\u10d8\u10e8\u10d8"},
ge9(){return"\u10d0\u10db \u10d4\u10da.\u10e4\u10dd\u10e1\u10e2\u10d0\u10d6\u10d4 \u10d0\u10e0 \u10d0\u10e0\u10e1\u10d4\u10d1\u10dd\u10d1\u10e1 Edhomy \u10d0\u10dc\u10d2\u10d0\u10e0\u10d8\u10e8\u10d8"},
geC(){return"\u10e8\u10d4\u10e1\u10d5\u10da\u10d0 \u10e8\u10d4\u10e1\u10d0\u10eb\u10da\u10d4\u10d1\u10d4\u10da\u10d8\u10d0 \u10db\u10ee\u10dd\u10da\u10dd\u10d3 \u10d4\u10da.\u10e4\u10dd\u10e1\u10e2\u10d8\u10e1 \u10d3\u10d0 \u10de\u10d0\u10e0\u10dd\u10da\u10d8\u10e1 \u10e8\u10d4\u10e7\u10d5\u10d0\u10dc\u10d8\u10d7"},
gdB(){return"\u10d8\u10dc\u10e1\u10e2\u10d0\u10d2\u10e0\u10d0\u10db\u10d8"},
gdU(){return"\u10d8\u10e3\u10d7\u10e3\u10d1\u10d8"},
gdN(){return"\u10e2\u10d8\u10d9\u10e2\u10dd\u10d9\u10d8"},
